  "航天": { meaningMy: "အာကာသပျံသန်းရေး၊ ကမ္ဘာ့လေထုအပြင်ဘက်သို့ ယာဉ်လွှတ်ပျံသန်းသည့် သိပ္ပံနည်းပညာ" },
  "航行": { meaningMy: "သင်္ဘော သို့မဟုတ် လေယာဉ်ဖြင့် သတ်မှတ်လမ်းကြောင်းအတိုင်း သွားလာသည်" },
  "行列": { meaningMy: "တန်းစီထားသောအုပ်စု၊ တူညီသည့်အဖွဲ့ သို့မဟုတ် လူတန်းစားအတွင်း ပါဝင်မှု" },
  "豪迈": { meaningMy: "ရဲရင့်ရက်ရော၍ စိတ်ဓာတ်မြင့်မားသော" },
  "毫米": { meaningMy: "မီလီမီတာ၊ တစ်မီတာ၏ တစ်ထောင်ပုံတစ်ပုံ အလျားယူနစ်" },
  "毫无": { meaningMy: "လုံးဝမရှိသော၊ အနည်းငယ်မျှပင် မရှိသော" },
  "号召": { meaningMy: "ရည်မှန်းချက်တစ်ခုအတွက် လူထုကို ပါဝင်ဆောင်ရွက်ရန် တိုက်တွန်းနှိုးဆော်သည်" },
  "耗费": { meaningMy: "အချိန်၊ အင်အား သို့မဟုတ် ငွေကြေးကို များစွာသုံးစွဲကုန်ကျသည်" },
  "好客": { meaningMy: "ဧည့်ဝတ်ကျေပွန်သော၊ ဧည့်သည်များကို နွေးထွေးစွာ ကြိုဆိုတတ်သော" },
  "呵": { meaningMy: "ပါးစပ်မှ လေငွေ့မှုတ်ထုတ်သည်၊ အံ့အားသင့်မှု သို့မဟုတ် ခံစားချက်ပြသည့် အသံ" },
  "和蔼": { meaningMy: "ဖော်ရွေကြင်နာသော၊ သဘောထားနူးညံ့၍ ချဉ်းကပ်ရလွယ်သော" },
  "和解": { meaningMy: "အငြင်းပွားမှုကို ညှိနှိုင်းသဘောတူ၍ ပြေလည်စေသည်၊ ဥပဒေအရ ကျေအေးသဘောတူသည်" },
  "和睦": { meaningMy: "သင့်မြတ်ချစ်ခင်သော၊ အချင်းချင်း အငြင်းပွားမှုမရှိဘဲ ငြိမ်းချမ်းစွာ ဆက်ဆံသော" },
