  "合成": { meaningMy: "အစိတ်အပိုင်းများကို ပေါင်းစပ်၍ အရာသစ်တစ်ခု ဖန်တီးသည်၊ ဓာတုနည်းဖြင့် ပေါင်းစပ်ထုတ်လုပ်သည်" },
