  "合伙": { meaningMy: "အရင်းအနှီး သို့မဟုတ် အားထုတ်မှု ပူးပေါင်း၍ လုပ်ငန်းအတူလုပ်သည်" },
  "合身": { meaningMy: "အဝတ်အစား ကိုယ်ခန္ဓာအရွယ်နှင့် ကွက်တိကိုက်ညီသော" },
  "合算": { meaningMy: "တွက်ခြေကိုက်သော၊ ကုန်ကျစရိတ်နှင့် အကျိုးရလဒ်အရ တန်သော" },
  "嘿": { meaningMy: "ဟေး၊ အာရုံစိုက်စေရန် ခေါ်ခြင်း သို့မဟုတ် အံ့အားသင့်မှုဖော်ပြသည့် အသံ" },
  "痕迹": { meaningMy: "အမှတ်အသား၊ ဖြစ်ရပ် သို့မဟုတ် လှုပ်ရှားမှုတစ်ခု ကျန်ရစ်ခဲ့သည့် ခြေရာ" },
  "狠心": { meaningMy: "ရက်စက်စိတ်ရှိသော၊ သနားညှာတာမှုကို ဘေးဖယ်၍ ပြတ်ပြတ်သားသားလုပ်သော" },
  "恨不得": { meaningMy: "တစ်စုံတစ်ရာကို ချက်ချင်းလုပ်နိုင်ရန် အလွန်တောင့်တသည်" },
  "哼": { meaningMy: "နှာခေါင်းမှ အသံပြုသည်၊ မကျေနပ်မှု သို့မဟုတ် သံသယကို အသံဖြင့်ဖော်ပြသည်" },
  "哄": { meaningMy: "လူအများ တပြိုင်နက် ဆူညံရယ်မောသည်၊ ချော့မော့သည် သို့မဟုတ် လိမ်လည်ဖြားယောင်းသည်" },
  "烘": { meaningMy: "မီး သို့မဟုတ် အပူဖြင့် ကင်ခြောက်သည်၊ ဖုတ်သည်" },
  "轰动": { meaningMy: "လူထုအတွင်း အကြီးအကျယ် အာရုံစိုက်လှုပ်ရှားစေသည်၊ အုတ်အော်သောင်းနင်းဖြစ်စေသည်" },
  "红包": { meaningMy: "အနီရောင်စာအိတ်ဖြင့် ပေးသော ငွေလက်ဆောင်၊ အခမ်းအနားဆိုင်ရာ ဆုငွေ" },
  "宏观": { meaningMy: "ခြုံငုံကျယ်ပြန့်သော ရှုထောင့်၊ စီးပွားရေး သို့မဟုတ် လူမှုစနစ်တစ်ခုလုံးကို ကြည့်သော" },
