  "忽略": { meaningMy: "လျစ်လျူရှုသည်၊ အရေးပါသည့်အချက်ကို သတိမပြုဘဲ ကျော်လွန်သည်" },
  "呼啸": { meaningMy: "လေ၊ ယာဉ် သို့မဟုတ် ကျည်ဆန်ကဲ့သို့ အရာက စူးရှစွာ မြည်ဟည်းဖြတ်သန်းသည်" },
