  "花瓣": { meaningMy: "ပန်းဖတ်၊ ပန်းပွင့်၏ အရောင်ရှိသော အရွက်ပုံအစိတ်အပိုင်း" },
  "华丽": { meaningMy: "ခမ်းနားလှပသော၊ အရောင်အသွေးနှင့် အလှဆင်မှု ထူးကဲသော" },
