  "化肥": { meaningMy: "ဓာတ်မြေဩဇာ၊ ဓာတုနည်းဖြင့် ထုတ်လုပ်သော စိုက်ပျိုးရေးမြေဩဇာ" },
  "化石": { meaningMy: "ကျောက်ဖြစ်ရုပ်ကြွင်း၊ ရှေးသက်ရှိများ၏ အစိတ်အပိုင်း သို့မဟုတ် ခြေရာ ကျောက်လွှာတွင် ထိန်းသိမ်းကျန်ရစ်မှု" },
  "化验": { meaningMy: "ဓာတ်ခွဲစမ်းသပ်သည်၊ နမူနာကို ဓာတု သို့မဟုတ် ဆေးဘက်ဆိုင်ရာနည်းဖြင့် စစ်ဆေးသည်" },
