  "还原": { meaningMy: "မူလအခြေအနေသို့ ပြန်လည်ရောက်ရှိစေသည်၊ ဓာတုဗေဒတွင် အီလက်ထရွန်လက်ခံသည့် လျှော့ချတုံ့ပြန်မှု" },
  "环节": { meaningMy: "လုပ်ငန်းစဉ်တစ်ခု၏ အဆင့် သို့မဟုတ် အပြန်အလှန်ဆက်စပ်နေသော အပိုင်း" },
  "缓和": { meaningMy: "တင်းမာမှု သို့မဟုတ် ပြင်းထန်မှုကို လျော့ပါးပြေလျော့စေသည်" },
  "患者": { meaningMy: "လူနာ၊ ရောဂါခံစားနေရ၍ ဆေးကုသမှုခံယူသူ" },
  "荒凉": { meaningMy: "လူသူကင်းမဲ့၍ စည်ပင်မှုမရှိသော၊ ခြောက်ကပ်တိတ်ဆိတ်သော" },
  "荒谬": { meaningMy: "အကြောင်းအကျိုးမညီ၍ လုံးဝမဖြစ်နိုင်သော၊ ယုတ္တိမဲ့သော" },
  "荒唐": { meaningMy: "အဓိပ္ပာယ်မရှိ၍ ယုံကြည်ရန်ခက်သော၊ အလွန်မသင့်လျော်သော" },
