  "黄昏": { meaningMy: "နေဝင်ဆည်းဆာအချိန်၊ နေဝင်ပြီး အလင်းမပျောက်မီအချိန်" },
  "恍然大悟": { meaningMy: "မရှင်းလင်းခဲ့သည့်အရာကို ရုတ်တရက် အပြည့်အဝ သဘောပေါက်နားလည်သည်" },
  "挥霍": { meaningMy: "ငွေကြေး၊ အချိန် သို့မဟုတ် အရင်းအမြစ်ကို အလွန်အကျွံ ဖြုန်းတီးသည်" },
