  "技能": { meaningMy: "ကျွမ်းကျင်မှု၊ လေ့ကျင့်သင်ယူခြင်းဖြင့် ရရှိသော လုပ်ငန်းဆောင်ရွက်နိုင်စွမ်း" },
  "技巧": { meaningMy: "နည်းစနစ်နှင့် ကျွမ်းကျင်လိမ္မာမှု၊ အလုပ်ကို ထိရောက်စွာ ဆောင်ရွက်သည့်နည်း" },
  "迹象": { meaningMy: "လက္ခဏာ၊ ဖြစ်ပေါ်လာနိုင်သည့် အခြေအနေကို ညွှန်ပြသော အမှတ်အသား" },
  "家常": { meaningMy: "အိမ်တွင်းနေ့စဉ်ဘဝနှင့် သက်ဆိုင်သော၊ ရိုးရိုးအိမ်ချက်အစားအစာ" },
