  "夹杂": { meaningMy: "မတူညီသော အရာများ ကြားထဲ ရောနှောပါဝင်နေသည်" },
  "假设": { meaningMy: "ယာယီမှန်ကန်သည်ဟု ယူဆထားသော အခြေအနေ သို့မဟုတ် သိပ္ပံဆိုင်ရာ အယူအဆ" },
  "假使": { meaningMy: "အကယ်၍၊ အခြေအနေတစ်ရပ်ကို ခန့်မှန်းတင်ပြသည့် ဆက်စပ်စကား" },
  "坚定": { meaningMy: "ယုံကြည်ချက်နှင့် ရပ်တည်ချက် ခိုင်မာ၍ မယိမ်းယိုင်သော" },
  "坚固": { meaningMy: "ဖွဲ့စည်းပုံ ခိုင်ခံ့၍ အလွယ်တကူ မပျက်စီးသော" },
