  "监督": { meaningMy: "ဥပဒေ၊ စည်းမျဉ်းနှင့် သတ်မှတ်ချက်များအတိုင်း ဆောင်ရွက်ခြင်းရှိမရှိ စောင့်ကြည့်စစ်ဆေးသည်" },
  "监视": { meaningMy: "လူ၊ နေရာ သို့မဟုတ် လှုပ်ရှားမှုကို အနီးကပ် ဆက်တိုက်စောင့်ကြည့်သည်" },
  "监狱": { meaningMy: "အကျဉ်းထောင်၊ ပြစ်ဒဏ်ချမှတ်ခံရသူများကို ဥပဒေအရ ချုပ်နှောင်ထားသည့်နေရာ" },
