  "践踏": { meaningMy: "ခြေဖြင့် နင်းချေသည်၊ အခွင့်အရေး သို့မဟုတ် ဂုဏ်သိက္ခာကို ရက်စက်စွာ ချိုးဖောက်သည်" },
