  "交涉": { meaningMy: "အကျိုးစီးပွား သို့မဟုတ် အငြင်းပွားမှုအတွက် သက်ဆိုင်သူနှင့် တရားဝင်ညှိနှိုင်းဆွေးနွေးသည်" },
