  "阶层": { meaningMy: "လူမှုအလွှာ၊ စီးပွားရေး၊ အလုပ်အကိုင် သို့မဟုတ် အဆင့်အတန်းတူသူများ၏ အုပ်စု" },
  "揭发": { meaningMy: "ပြစ်မှု၊ အမှား သို့မဟုတ် မကောင်းမှုကို အာဏာပိုင် သို့မဟုတ် အများပြည်သူထံ ဖော်ထုတ်တိုင်ကြားသည်" },
  "揭露": { meaningMy: "ဖုံးကွယ်ထားသော အမှန်တရား သို့မဟုတ် ပြဿနာကို လူသိရှင်ကြား ဖော်ထုတ်သည်" },
  "节奏": { meaningMy: "စည်းချက်၊ အသံ၊ လှုပ်ရှားမှု သို့မဟုတ် လုပ်ငန်း၏ ပုံမှန်မြန်နှုန်းနှင့် အစီအစဉ်" },
  "杰出": { meaningMy: "သာမန်ထက် ထူးချွန်ပြောင်မြောက်သော" },
  "结晶": { meaningMy: "ပုံဆောင်ခဲဖွဲ့စည်းမှု၊ အချိန်ကြာအားထုတ်မှုမှ ရရှိသော ထူးခြားသည့် ရလဒ်" },
  "结局": { meaningMy: "နိဂုံးရလဒ်၊ ဖြစ်ရပ် သို့မဟုတ် ဇာတ်လမ်း၏ နောက်ဆုံးအခြေအနေ" },
  "结算": { meaningMy: "ငွေစာရင်းကို အပြီးသတ်တွက်ချက်၍ ပေးချေရှင်းလင်းသည်" },
  "竭尽全力": { meaningMy: "မိမိတွင်ရှိသမျှ အင်အားနှင့် စွမ်းရည်အားလုံးကို အကုန်အသုံးပြုကြိုးပမ်းသည်" },
  "截至": { meaningMy: "သတ်မှတ်ထားသော အချိန်အထိ၊ ထိုအချိန်တွင် အဆုံးသတ်ကန့်သတ်၍" },
  "解除": { meaningMy: "ကန့်သတ်ချက်၊ တာဝန်၊ သဘောတူညီချက် သို့မဟုတ် အန္တရာယ်ကို ပယ်ဖျက်ဖယ်ရှားသည်" },
  "解雇": { meaningMy: "အလုပ်ရှင်က အလုပ်သမားနှင့် အလုပ်ခန့်ထားမှုဆက်ဆံရေးကို ရပ်စဲ၍ အလုပ်မှထုတ်ပယ်သည်" },
  "解剖": { meaningMy: "ကိုယ်ခန္ဓာဖွဲ့စည်းပုံကို လေ့လာရန် ခွဲစိတ်စစ်ဆေးသည်" },
  "解散": { meaningMy: "အဖွဲ့အစည်းကို တရားဝင်ဖျက်သိမ်းသည်၊ စုဝေးနေသူများ ခွဲခွာသွားစေသည်" },
  "解体": { meaningMy: "ဖွဲ့စည်းထားသည့်အရာ အစိတ်အပိုင်းများအဖြစ် ပြိုကွဲသည် သို့မဟုတ် ဖြုတ်ခွဲသည်" },
  "借鉴": { meaningMy: "အခြားသူ၏ အတွေ့အကြုံ သို့မဟုတ် နည်းလမ်းကို ကိုးကားသင်ယူ၍ မိမိလုပ်ငန်းတွင် အသုံးချသည်" },
  "借助": { meaningMy: "လူ၊ ကိရိယာ သို့မဟုတ် အခြေအနေတစ်ရပ်၏ အကူအညီကို အသုံးပြုသည်" },
  "戒备": { meaningMy: "ဖြစ်နိုင်သော အန္တရာယ် သို့မဟုတ် တိုက်ခိုက်မှုကို ကာကွယ်ရန် သတိဖြင့် အသင့်ပြင်ထားသည်" },
  "界限": { meaningMy: "နယ်နိမိတ်၊ အရာနှစ်ခု၏ အတိုင်းအတာ သို့မဟုတ် သဘောတရားကို ခွဲခြားသည့် မျဉ်း" },
  "津津有味": { meaningMy: "အလွန်စိတ်ဝင်စားအားရစွာ ခံစား သို့မဟုတ် ပြောဆိုနေသော" },
  "金融": { meaningMy: "ဘဏ္ဍာရေး၊ ငွေကြေး၊ ချေးငွေ၊ ရင်းနှီးမြှုပ်နှံမှုနှင့် အရင်းအနှီးလည်ပတ်မှုဆိုင်ရာ လုပ်ငန်းကဏ္ဍ" },
  "紧密": { meaningMy: "အလွန်နီးကပ်ခိုင်မာစွာ ဆက်စပ်နေသော၊ ကြားလပ်မရှိအောင် တင်းကျပ်သော" },
  "紧迫": { meaningMy: "အချိန် သို့မဟုတ် အခြေအနေ အလွန်အရေးတကြီးဖြစ်၍ ချက်ချင်းဆောင်ရွက်ရန်လိုသော" },
  "尽快": { meaningMy: "တတ်နိုင်သမျှ အမြန်ဆုံး" },
  "锦绣前程": { meaningMy: "တောက်ပလှပ၍ အောင်မြင်မှုများသော အနာဂတ်လမ်းခရီး" },
  "进而": { meaningMy: "ထိုအခြေခံမှ တစ်ဆင့်တိုး၍၊ ဆက်လက်ပြီး ပိုမိုနက်ရှိုင်းစွာ" },
  "进攻": { meaningMy: "ရန်သူ သို့မဟုတ် ပြိုင်ဘက်ဘက်သို့ တက်ရောက်တိုက်ခိုက်သည်" },
  "进化": { meaningMy: "ဆင့်ကဲပြောင်းလဲသည်၊ သက်ရှိမျိုးစိတ်နှင့် စနစ်များ အချိန်ကြာလာသည်နှင့် ပြောင်းလဲဖွံ့ဖြိုးသည်" },
  "进展": { meaningMy: "လုပ်ငန်း သို့မဟုတ် အခြေအနေ ရှေ့သို့တိုးတက်လာမှု" },
  "近来": { meaningMy: "မကြာသေးမီကာလအတွင်း၊ လတ်တလောတွင်" },
  "近视": { meaningMy: "အနီးမှုန်၊ အနီးရှိအရာကို ရှင်းမြင်သော်လည်း အဝေးကို မရှင်းလင်းစွာမြင်ရသည့် မျက်စိအခြေအနေ" },
  "浸泡": { meaningMy: "အရည်ထဲတွင် အချိန်ကြာ စိမ်ထားသည်" },
  "晋升": { meaningMy: "ပိုမိုမြင့်မားသော ရာထူး သို့မဟုတ် အဆင့်သို့ တိုးမြှင့်ခန့်အပ်သည်" },
  "劲头": { meaningMy: "လုပ်ဆောင်လိုသည့် စိတ်အားနှင့် အင်အား၊ တက်ကြွစိတ်အားထက်သန်မှု" },
  "茎": { meaningMy: "ပင်စည်၊ အရွက်၊ ပန်းနှင့် အသီးကို ထောက်ပံ့သယ်ဆောင်သည့် အပင်အစိတ်အပိုင်း" },
  "精打细算": { meaningMy: "ငွေကြေးနှင့် အရင်းအမြစ်ကို အသေးစိတ်တွက်ချက်၍ ချွေတာစနစ်တကျ အသုံးပြုသည်" },
