  "口气": { meaningMy: "စကားပြောသံနှင့် သဘောထား၊ ပါးစပ်မှ ထွက်သောအနံ့ သို့မဟုတ် အသက်ရှူငွေ့" },
  "口腔": { meaningMy: "ခံတွင်း၊ နှုတ်ခမ်းမှ လည်ချောင်းအဝအထိရှိသော ပါးစပ်အတွင်းပိုင်း" },
