  "捆绑": { meaningMy: "ကြိုး သို့မဟုတ် အခြားပစ္စည်းဖြင့် ချည်နှောင်စည်းသည်၊ အကျိုးစီးပွားများကို အတင်းအကျပ် ပေါင်းစည်းသည်" },
  "扩充": { meaningMy: "အင်အား၊ အကြောင်းအရာ သို့မဟုတ် အရွယ်အစားကို ထပ်မံဖြည့်တင်းချဲ့ထွင်သည်" },
