  "启程": { meaningMy: "ခရီးစတင်ထွက်ခွာသည်" },
  "启示": { meaningMy: "အတွေ့အကြုံ သို့မဟုတ် ဖြစ်ရပ်မှ ရရှိသော နားလည်မှုနှင့် လမ်းညွှန်သင်ခန်းစာ" },
  "启事": { meaningMy: "အများပြည်သူသိရှိရန် စာဖြင့် ထုတ်ပြန်သည့် အကြောင်းကြားစာ" },
  "乞丐": { meaningMy: "သူတောင်းစား၊ အခြားသူများထံ အစားအစာ သို့မဟုတ် ငွေကြေး တောင်းခံ၍ အသက်မွေးသူ" },
  "岂有此理": { meaningMy: "ဤသို့ဖြစ်ရသည်မှာ လုံးဝအကြောင်းမရှိ၊ အလွန်မတရားမသင့်လျော်ကြောင်း ဒေါသဖြင့် ပြောသောစကား" },
  "器材": { meaningMy: "လုပ်ငန်း၊ အားကစား၊ ဆေးဘက် သို့မဟုတ် သိပ္ပံအတွက် အသုံးပြုသည့် ကိရိယာနှင့် ပစ္စည်းများ" },
  "器官": { meaningMy: "ကိုယ်အင်္ဂါ၊ သက်ရှိခန္ဓာကိုယ်တွင် သတ်မှတ်လုပ်ဆောင်ချက်ရှိသော တစ်ရှူးဖွဲ့စည်းပုံ" },
  "气概": { meaningMy: "ရဲရင့်မြင့်မြတ်သော စိတ်ဓာတ်နှင့် အမူအရာ" },
  "气功": { meaningMy: "ချီကုန်း၊ အသက်ရှူခြင်း၊ ကိုယ်ဟန်နှင့် စိတ်အာရုံကို ပေါင်းစပ်လေ့ကျင့်သည့် တရုတ်ရိုးရာကျန်းမာရေးလေ့ကျင့်ခန်း" },
  "气魄": { meaningMy: "ရဲရင့်ပြတ်သားသော စိတ်အင်အားနှင့် အရာကြီးကို ဆောင်ရွက်နိုင်သည့် အမြင်ကျယ်မှု" },
  "气色": { meaningMy: "မျက်နှာအရောင်နှင့် ကျန်းမာရေးအခြေအနေကို ဖော်ပြသော အသွင်အပြင်" },
  "气势": { meaningMy: "အားကောင်းခမ်းနား၍ လူကို လွှမ်းမိုးသည့် အင်အားနှင့် အမူအရာ" },
  "气味": { meaningMy: "အနံ့၊ အရာဝတ္ထုမှ ထွက်ပေါ်၍ နှာခေါင်းဖြင့် ခံစားရသော ဓာတ်ငွေ့သဘော" },
  "气象": { meaningMy: "မိုးလေဝသဖြစ်စဉ်များ၊ အဖွဲ့ သို့မဟုတ် အခြေအနေ၏ ခြုံငုံအသွင်အပြင်" },
  "气压": { meaningMy: "လေထုဖိအား၊ လေထုက တစ်ယူနစ်မျက်နှာပြင်ပေါ် သက်ရောက်သောအား" },
  "迄今为止": { meaningMy: "ယခုအချိန်အထိ၊ အတိတ်မှ လက်ရှိအချိန်အထိ" },
  "掐": { meaningMy: "လက်သည်း သို့မဟုတ် လက်ချောင်းဖြင့် ဖိညှပ်သည်၊ ပန်း သို့မဟုတ် အပင်ကို ဖြတ်ယူသည်" },
  "恰当": { meaningMy: "အခြေအနေ၊ ရည်ရွယ်ချက်နှင့် စံနှုန်းတို့နှင့် သင့်လျော်ကိုက်ညီသော" },
  "恰到好处": { meaningMy: "ပိုလည်းမပို လျော့လည်းမလျော့ဘဲ လိုအပ်သည့်အတိုင်း အတိအကျ သင့်တော်သော" },
  "恰巧": { meaningMy: "တိုက်တိုက်ဆိုင်ဆိုင်၊ အချိန်နှင့် အခြေအနေ အတော်တဆ ကိုက်ညီစွာ" },
  "洽谈": { meaningMy: "စီးပွားရေး သို့မဟုတ် ပူးပေါင်းဆောင်ရွက်မှုကိစ္စကို နှစ်ဖက်ညှိနှိုင်းဆွေးနွေးသည်" },
  "牵扯": { meaningMy: "လူ သို့မဟုတ် ကိစ္စအများကို ဆက်နွယ်ပါဝင်စေသည်၊ ကိစ္စတစ်ခုတွင် ပါဝင်ပတ်သက်သည်" },
  "牵制": { meaningMy: "အခြားဘက်၏ အင်အားနှင့် လှုပ်ရှားမှုကို ချုပ်ကိုင်တားဆီး၍ လွတ်လပ်စွာ မလုပ်နိုင်အောင် ထိန်းထားသည်" },
