  "签订": { meaningMy: "ညှိနှိုင်းပြီးသော စာချုပ် သို့မဟုတ် သဘောတူညီချက်ကို လက်မှတ်ရေးထိုး၍ တရားဝင်ချုပ်ဆိုသည်" },
  "签署": { meaningMy: "စာချုပ်၊ ကြေညာချက် သို့မဟုတ် တရားဝင်စာရွက်စာတမ်းပေါ်တွင် လက်မှတ်ရေးထိုးသည်" },
  "迁就": { meaningMy: "အခြားသူ၏ ဆန္ဒ သို့မဟုတ် အခြေအနေကို လိုက်လျောရန် မိမိစံနှုန်းကို လျှော့ချသည်" },
  "迁徙": { meaningMy: "လူ သို့မဟုတ် တိရစ္ဆာန်အုပ်စု နေရာတစ်ခုမှ အခြားနေရာသို့ ရာသီအလိုက် သို့မဟုတ် ရေရှည် ရွှေ့ပြောင်းသည်" },
  "谦逊": { meaningMy: "မိမိကိုယ်ကို မမြှောက်စားဘဲ နှိမ့်ချယဉ်ကျေးသော" },
  "前景": { meaningMy: "အနာဂတ်ဖွံ့ဖြိုးတိုးတက်နိုင်မှုနှင့် မျှော်မှန်းရလဒ်၊ မြင်ကွင်း၏ ရှေ့ပိုင်း" },
  "前提": { meaningMy: "နိဂုံး သို့မဟုတ် လုပ်ဆောင်ချက်တစ်ရပ် တည်ရှိနိုင်ရန် ကြိုတင်လိုအပ်သည့် အခြေအနေ" },
  "潜力": { meaningMy: "မဖော်ထုတ်ရသေးသော်လည်း အနာဂတ်တွင် ဖွံ့ဖြိုးအသုံးချနိုင်သည့် စွမ်းရည်" },
  "潜水": { meaningMy: "ရေအောက်သို့ ငုပ်၍ လှုပ်ရှား သို့မဟုတ် အလုပ်လုပ်သည်" },
  "潜移默化": { meaningMy: "မသိမသာနှင့် အချိန်ကြာလာသည်နှင့် အတွေး၊ အကျင့် သို့မဟုတ် စရိုက်ကို တဖြည်းဖြည်း ပြောင်းလဲသက်ရောက်စေသည်" },
  "谴责": { meaningMy: "မမှန်ကန်သော သို့မဟုတ် အန္တရာယ်ရှိသော လုပ်ရပ်ကို ပြင်းထန်စွာ အပြစ်တင်ရှုတ်ချသည်" },
  "强制": { meaningMy: "ဥပဒေ သို့မဟုတ် အာဏာသုံး၍ မဖြစ်မနေ လိုက်နာလုပ်ဆောင်စေသည်" },
  "抢劫": { meaningMy: "အကြမ်းဖက်မှု သို့မဟုတ် ခြိမ်းခြောက်မှုဖြင့် သူတစ်ပါးပစ္စည်းကို လုယူသည်" },
  "抢救": { meaningMy: "အရေးပေါ်အန္တရာယ်ရှိသူ သို့မဟုတ် ပစ္စည်းကို အချိန်မီ ကယ်တင်ကုသသည်" },
  "强迫": { meaningMy: "ဆန္ဒမရှိသူကို ဖိအား သို့မဟုတ် အာဏာသုံး၍ လုပ်ဆောင်စေသည်" },
  "桥梁": { meaningMy: "တံတား၊ နှစ်ဖက် သို့မဟုတ် လူအုပ်စုများကို ဆက်သွယ်ပေးသည့် ကြားခံ" },
  "翘": { meaningMy: "တစ်ဖက်စွန်း အပေါ်သို့ ထောင်တက်သည်၊ အစီအစဉ် သို့မဟုတ် အလုပ်ကို ပျက်ကွက်ရှောင်သည်" },
  "锲而不舍": { meaningMy: "ရည်မှန်းချက်ကို မစွန့်လွှတ်ဘဲ အဆက်မပြတ် ဇွဲရှိရှိ ကြိုးပမ်းသည်" },
  "切实": { meaningMy: "လက်တွေ့အခြေအနေနှင့် ကိုက်ညီ၍ ထိရောက်သော၊ အမှန်တကယ် အကောင်အထည်ဖော်သော" },
  "亲热": { meaningMy: "ချစ်ခင်ရင်းနှီး၍ နွေးထွေးစွာ ဆက်ဆံသော" },
  "亲身": { meaningMy: "ကိုယ်တိုင်၊ အခြားသူမှတစ်ဆင့်မဟုတ်ဘဲ မိမိကိုယ်တိုင် ပါဝင်ကြုံတွေ့သော" },
  "侵犯": { meaningMy: "အခြားသူ၏ အခွင့်အရေး၊ ကိုယ်ပိုင်နယ်ပယ် သို့မဟုတ် နိုင်ငံပိုင်နက်ကို ဥပဒေမဲ့ ကျူးကျော်ချိုးဖောက်သည်" },
  "钦佩": { meaningMy: "အရည်အချင်း သို့မဟုတ် ကိုယ်ကျင့်တရားကြောင့် လေးစားအားကျသည်" },
