  "氢": { meaningMy: "ဟိုက်ဒရိုဂျင်၊ သင်္ကေတ H နှင့် အက်တမ်နံပါတ် ၁ ရှိသော အပေါ့ပါးဆုံး ဓာတုဒြပ်စင်" },
  "轻而易举": { meaningMy: "အားထုတ်မှုများစွာမလိုဘဲ အလွယ်တကူ ဆောင်ရွက်နိုင်သော" },
  "清澈": { meaningMy: "ရေ သို့မဟုတ် အရည် ကြည်လင်သန့်ရှင်း၍ အောက်ခြေမြင်ရသော" },
  "清晨": { meaningMy: "နေထွက်ခါစ မနက်စောစောအချိန်" },
